import java.util.*;

public class Main {
    // Dependency graph: artifact -> list of {child, version} in declaration order
    static Map<String, List<String[]>> graph = new HashMap<>();

    static void resolve(List<String[]> direct) {
        // Breadth-first walk: the shallowest path wins ("nearest wins"), ties go to first declared
        Map<String, String> chosen = new HashMap<>();
        Deque<String[]> queue = new ArrayDeque<>(direct);
        while (!queue.isEmpty()) {
            String[] d = queue.poll();
            if (chosen.containsKey(d[0])) {
                System.out.println("  omit " + d[0] + ":" + d[1] + " (conflict with " + chosen.get(d[0]) + ")");
                continue;
            }
            chosen.put(d[0], d[1]);
            System.out.println("  pick " + d[0] + ":" + d[1]);
            queue.addAll(graph.getOrDefault(d[0], new ArrayList<>())); // children of a loser are never added
        }
        System.out.println("  => C resolves to " + chosen.get("C"));
    }

    public static void main(String[] args) {
        graph.put("app", Arrays.asList(new String[]{"A", "1.0"}, new String[]{"B", "1.0"}));
        graph.put("A", Collections.singletonList(new String[]{"C", "1.0"}));
        graph.put("B", Collections.singletonList(new String[]{"D", "1.0"}));
        graph.put("D", Collections.singletonList(new String[]{"C", "2.0"}));
        System.out.println("Scenario 1: transitive only");
        resolve(graph.get("app"));
        System.out.println("Scenario 2: app pins C:3.0 directly");
        List<String[]> pinned = new ArrayList<>();
        pinned.add(new String[]{"C", "3.0"});
        pinned.addAll(graph.get("app"));
        resolve(pinned);
    }
}

