#include <bits/stdc++.h>
using namespace std;
typedef pair<string, string> Dep;

// Dependency graph: artifact -> list of (child, version) in declaration order
map<string, vector<Dep>> graph = {
    {"app", {{"A", "1.0"}, {"B", "1.0"}}},
    {"A", {{"C", "1.0"}}},
    {"B", {{"D", "1.0"}}},
    {"D", {{"C", "2.0"}}},
};

void resolve(const vector<Dep>& direct) {
    // Breadth-first walk: the shallowest path wins ("nearest wins"), ties go to first declared
    map<string, string> chosen;
    deque<Dep> queue(direct.begin(), direct.end());
    while (!queue.empty()) {
        Dep d = queue.front();
        queue.pop_front();
        if (chosen.count(d.first)) {
            cout << "  omit " << d.first << ":" << d.second << " (conflict with " << chosen[d.first] << ")\n";
            continue;
        }
        chosen[d.first] = d.second;
        cout << "  pick " << d.first << ":" << d.second << "\n";
        for (auto& c : graph[d.first]) queue.push_back(c); // children of a loser are never added
    }
    cout << "  => C resolves to " << chosen["C"] << "\n";
}

int main() {
    cout << "Scenario 1: transitive only\n";
    resolve(graph["app"]);
    cout << "Scenario 2: app pins C:3.0 directly\n";
    vector<Dep> pinned = {{"C", "3.0"}};
    for (auto& d : graph["app"]) pinned.push_back(d);
    resolve(pinned);
}

