using System;
using System.Collections.Generic;

class Program
{
    // Dependency graph: artifact -> list of {child, version} in declaration order
    static Dictionary<string, List<string[]>> graph = new Dictionary<string, List<string[]>>();

    static void Resolve(List<string[]> direct)
    {
        // Breadth-first walk: the shallowest path wins ("nearest wins"), ties go to first declared
        var chosen = new Dictionary<string, string>();
        var queue = new Queue<string[]>(direct);
        while (queue.Count > 0)
        {
            string[] d = queue.Dequeue();
            if (chosen.ContainsKey(d[0]))
            {
                Console.WriteLine("  omit " + d[0] + ":" + d[1] + " (conflict with " + chosen[d[0]] + ")");
                continue;
            }
            chosen[d[0]] = d[1];
            Console.WriteLine("  pick " + d[0] + ":" + d[1]);
            List<string[]> kids;
            if (graph.TryGetValue(d[0], out kids))
                foreach (var k in kids) queue.Enqueue(k); // children of a loser are never added
        }
        Console.WriteLine("  => C resolves to " + chosen["C"]);
    }

    static void Main()
    {
        graph["app"] = new List<string[]> { new[] { "A", "1.0" }, new[] { "B", "1.0" } };
        graph["A"] = new List<string[]> { new[] { "C", "1.0" } };
        graph["B"] = new List<string[]> { new[] { "D", "1.0" } };
        graph["D"] = new List<string[]> { new[] { "C", "2.0" } };
        Console.WriteLine("Scenario 1: transitive only");
        Resolve(graph["app"]);
        Console.WriteLine("Scenario 2: app pins C:3.0 directly");
        var pinned = new List<string[]> { new[] { "C", "3.0" } };
        pinned.AddRange(graph["app"]);
        Resolve(pinned);
    }
}

