public class Main {
    static int instances = 0;
    final int id;

    Main() { id = ++instances; System.out.println("  new test instance #" + id); }

    static void beforeAll() { System.out.println("@BeforeAll (once, static)"); }
    static void afterAll() { System.out.println("@AfterAll (once, static)"); }
    void beforeEach() { System.out.println("  @BeforeEach on instance #" + id); }
    void afterEach() { System.out.println("  @AfterEach on instance #" + id); }

    void run(String name) {
        System.out.println("  @Test " + name);
        if (name.equals("testB")) throw new AssertionError("expected 2 but was 3");
    }

    public static void main(String[] args) {
        beforeAll();
        for (String name : new String[]{"testA", "testB", "testC"}) {
            System.out.println("-- " + name);
            Main t = new Main();            // JUnit 5 creates a fresh instance per test method
            try {
                t.beforeEach();
                t.run(name);
            } catch (AssertionError e) {
                System.out.println("  FAILED: " + e.getMessage());
            } finally {
                t.afterEach();              // runs even when the test fails
            }
        }
        afterAll();
    }
}

public class Main {
    // Rule under test: shipping is free from 50.00 upward, otherwise 4.99 (amounts in cents)
    static int shipping(int orderCents) {
        return orderCents >= 5000 ? 0 : 499;
    }

    public static void main(String[] args) {
        // Each row: name, input, expected. A parameterized test runs one body over every row.
        Object[][] rows = {
            {"just below the limit", 4999, 499},
            {"exactly on the limit", 5000, 0},
            {"just above the limit", 5001, 0},
            {"empty order", 0, 499},
            {"large order", 100000, 0},
        };
        int failed = 0;
        for (Object[] row : rows) {
            String name = (String) row[0];
            int input = (Integer) row[1];
            int expected = (Integer) row[2];
            int actual = shipping(input);         // the shared act step
            boolean ok = actual == expected;      // the shared assert step
            if (!ok) failed++;
            System.out.println((ok ? "PASS " : "FAIL ") + name + ": shipping(" + input
                + ") = " + actual + ", expected " + expected);
        }
        System.out.println(rows.length - failed + "/" + rows.length + " rows passed");
    }
}

import java.util.*;

public class Main {
    interface Gateway { boolean charge(String user, int cents); }
    interface Repo { void save(String id, String v); String find(String id); }

    static class StubGateway implements Gateway {          // stub: canned answer
        public boolean charge(String u, int c) { return true; }
    }
    static class SpyGateway implements Gateway {           // spy: real behaviour plus a call log
        List<String> calls = new ArrayList<>();
        public boolean charge(String u, int c) { calls.add(u + ":" + c); return c > 0; }
    }
    static class FakeRepo implements Repo {                // fake: small working implementation
        Map<String, String> data = new HashMap<>();
        public void save(String id, String v) { data.put(id, v); }
        public String find(String id) { return data.get(id); }
    }
    static class MockGateway implements Gateway {          // mock: verified against expectations
        int expectedTimes, actualTimes;
        MockGateway(int expected) { expectedTimes = expected; }
        public boolean charge(String u, int c) { actualTimes++; return true; }
        void verify() { System.out.println("mock verify charge x" + expectedTimes + ": "
            + (actualTimes == expectedTimes ? "OK" : "FAILED, got " + actualTimes)); }
    }

    static boolean checkout(Gateway g, Repo r, String user, int cents) {
        boolean ok = g.charge(user, cents);
        if (ok) r.save("order-" + user, "PAID " + cents);
        return ok;
    }

    public static void main(String[] args) {
        FakeRepo repo = new FakeRepo();
        System.out.println("stub: checkout = " + checkout(new StubGateway(), repo, "u1", 500));
        System.out.println("fake: save then find -> " + repo.find("order-u1"));
        SpyGateway spy = new SpyGateway();
        checkout(spy, repo, "u2", 700);
        System.out.println("spy: recorded calls " + spy.calls);
        MockGateway mock = new MockGateway(1);
        checkout(mock, repo, "u3", 900);
        mock.verify();
    }
}
